SELECT 'SECTION','GROUP_SIDE_PATH';
SELECT COUNT(DISTINCT gm.groupId),COUNT(DISTINCT gm.memberGuid),SUM(leader_account.username LIKE 'RNDBOT%'),SUM(leader_account.username NOT LIKE 'RNDBOT%') FROM tw_char.group_member gm JOIN tw_char.characters member_char ON member_char.guid=gm.memberGuid JOIN tw_logon.account member_account ON member_account.id=member_char.account JOIN tw_char.groups g ON g.groupId=gm.groupId JOIN tw_char.characters leader_char ON leader_char.guid=g.leaderGuid JOIN tw_logon.account leader_account ON leader_account.id=leader_char.account WHERE member_account.username LIKE 'RNDBOT%';
SELECT 'SECTION','GROUP_SIDE_PATH_DETAILS_REDACTED';
SELECT gm.groupId,member_char.guid,member_char.name,member_char.online,IF(leader_account.username LIKE 'RNDBOT%','RNDBOT_LEADER','NON_RNDBOT_LEADER') FROM tw_char.group_member gm JOIN tw_char.characters member_char ON member_char.guid=gm.memberGuid JOIN tw_logon.account member_account ON member_account.id=member_char.account JOIN tw_char.groups g ON g.groupId=gm.groupId JOIN tw_char.characters leader_char ON leader_char.guid=g.leaderGuid JOIN tw_logon.account leader_account ON leader_account.id=leader_char.account WHERE member_account.username LIKE 'RNDBOT%' ORDER BY gm.groupId,member_char.guid;
SELECT 'SECTION','CANDIDATES';
SELECT c.guid,c.name,c.account,a.username,c.race,c.class,c.level,c.online,COALESCE(ev.add_value,0),COALESCE(ev.login_value,0),IF(gm.memberGuid IS NULL,0,1),GROUP_CONCAT(CONCAT(cs.skill,':',cs.value,'/',cs.max) ORDER BY cs.skill SEPARATOR ',') FROM tw_char.characters c JOIN tw_logon.account a ON a.id=c.account LEFT JOIN (SELECT bot,MAX(IF(event='add',value,0)) add_value,MAX(IF(event='login',value,0)) login_value FROM tw_char.ai_playerbot_random_bots WHERE owner=0 GROUP BY bot) ev ON ev.bot=c.guid LEFT JOIN tw_char.group_member gm ON gm.memberGuid=c.guid LEFT JOIN tw_char.character_skills cs ON cs.guid=c.guid AND cs.skill IN (164,165,171,182,186,197,202,333,393) WHERE a.username LIKE 'RNDBOT%' AND c.online=0 AND COALESCE(ev.add_value,0)=0 AND COALESCE(ev.login_value,0)=0 AND gm.memberGuid IS NULL GROUP BY c.guid,c.name,c.account,a.username,c.race,c.class,c.level,c.online,ev.add_value,ev.login_value,gm.memberGuid HAVING COUNT(cs.skill)>=1 ORDER BY c.level DESC,COUNT(cs.skill) DESC,c.guid LIMIT 50;